// Companion helpfulness index — record JAH-GAIS-AICOMPANION-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"ai_score": 85, "battery_h": 10, "price_usd": 200};
var value = (m.ai_score*m.battery_h/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GAIS-AICOMPANION-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GAIS-AICOMPANION-000001|' + value.toFixed(2) + ' helpfulness index');

